#!/usr/bin/env python3
"""Builds reports/token-naming-pilot.md (revised pilot plan + exact 11-variable final review). Read-only, deterministic.

Inputs: reports/token-naming/pilot-final-review-read.json (live read of the 11 variables, use_figma, read-only)
        reports/token-naming/pilot-preflight.json        (scripts/naming/pilot-rename.js preflight, no writes)
        reports/token-naming/audit.json                  (build-naming-audit.py: registry token, generated names, build handling)
        reports/token-naming/compile-check/results.json  (compile-check.mjs)
Usage: python3 -I scripts/naming/build-pilot-review.py
"""
import json, os
W = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
J = lambda p: json.load(open(os.path.join(W, p)))
rd = J('reports/token-naming/pilot-final-review-read.json')
pf = J('reports/token-naming/pilot-preflight.json')
au = J('reports/token-naming/audit.json')
cc = J('reports/token-naming/compile-check/results.json')
rows = {r['variableId']: r for r in au['rows']}
ORDER = [op['id'] for op in pf['ops']]

def hx(c):
    if isinstance(c, dict) and 'r' in c:
        s = '#' + ''.join(f'{round(c[k] * 255):02x}' for k in 'rgb')
        return s + (f"{round(c['a'] * 255):02x}" if c.get('a', 1) != 1 else '')
    return json.dumps(c) if not isinstance(c, (int, float)) else str(c)
def mode_str(modes):
    out = []
    for m, v in sorted(modes.items(), key=lambda x: (x[0] != 'Light mode', x[0])):
        if isinstance(v, dict) and v.get('alias'): out.append(f"{m}: → `{v['aliasName'].split(' › ')[1]}`")
        else: out.append(f"{m}: `{hx(v)}`")
    return '<br>'.join(out)
def short(n): return n.split(' › ', 1)[1] if ' › ' in n else n

L = ['# Token naming pilot — revision 2 (awaiting approval of the exact mapping)', '',
     '> 2026-11-09. Revised after Mike\'s naming decisions: convention **conditionally approved**; the 11 renames are **approved for final review only**; Node.js **approved for setup** (done: v26.13.0 LTS); radius **deferred**; Tailwind default overrides **blocked pending ADR-0009**; typography **revised to `type-*`**. Runs on the duplicate `PpnTy1pkB2FTZFq6i6seSy` only. **Nothing has been renamed.** No token-repo file changed. No screen work.', '',
     f"> Generated by `scripts/naming/build-pilot-review.py` from the live read-only read of the 11 variables ({rd['readAt']}), the rename preflight (no writes), `audit.json` and the compile check.", '',
     '## 1. What is decided and what is not', '',
     '| Item | Status |', '|---|---|',
     '| Two-tier naming architecture + deterministic Figma ↔ registry ↔ Tailwind ↔ NativeWind mapping | Conditionally approved (not a licence to rename everything) |',
     '| The 11 renames below | **Final review: need Mike\'s approval of this exact table before step 2** |',
     '| Radius | Deferred: no radius variable is in this batch, none is renamed |',
     '| Overriding Tailwind default theme keys | Blocked (ADR-0009). The pilot code-gen uses option A (roles only), which overrides nothing |',
     '| Composite typography | `type-*` proposal (convention §7). Not part of the Figma rename |', '',
     '## 2. Exact mapping (old → new)', '',
     'Rename = the `name` field only, by variable ID. Values, aliases, scopes, code syntax, `hiddenFromPublishing`, collection, modes and key stay unchanged.', '',
     '| # | Variable ID | Type | Collection | Old name | **New name** | Modes and values | Scopes · publishing |', '|---|---|---|---|---|---|---|---|']
for i, vid in enumerate(ORDER, 1):
    d = rd['detail'][vid]
    L.append(f"| {i} | `{vid}` | {d['resolvedType']} | `{d['collection']}` | `{d['name']}` | **`{d['proposed']}`** | {mode_str(d['modes'])} | {', '.join(d['scopes']) or '(none)'} · {'hidden' if d['hiddenFromPublishing'] else 'published'} |")
L += ['', '## 3. Alias relationships', '',
      'Aliases point to IDs, so every relationship below survives the rename unchanged. Names shown are the **current** names.', '',
      '| # | Old name | Aliases (its value points to) | Aliased by (variables whose value points to it) |', '|---|---|---|---|']
for i, vid in enumerate(ORDER, 1):
    d = rd['detail'][vid]
    to = sorted({f"`{v['aliasName'].split(' › ')[1]}`" for v in d['modes'].values() if isinstance(v, dict) and v.get('alias')})
    inpilot = {rd['detail'][x]['name'] for x in ORDER}
    by = [f"`{short(n)}`" + (' (in batch)' if short(n) in inpilot else '') for n in d['aliasedBy']]
    L.append(f"| {i} | `{d['name']}` | {', '.join(to) or '— (raw value)'} | {f'{len(by)}: ' + ', '.join(by) if by else '—'} |")
L += ['', 'Pairs inside the batch (both ends renamed; still resolve by ID): `bg-brand-primary` → `Brand/600`, `text-brand-primary` → `Brand/600` (Light), `border-primary` → `Gray (light mode)/450` (Light).', '',
      '## 4. Affected bindings and styles', '',
      'Counted on own layers of every main component (counting rule v2: one entry in `node.boundVariables`), plus layers outside components and local styles. These are the **expected unchanged counts** for verification after the rename.', '',
      '| # | Old name | Component bindings | Components (bindings) | Fields | Other layers | Styles referencing it |', '|---|---|---|---|---|---|---|']
tot = 0
for i, vid in enumerate(ORDER, 1):
    d = rd['detail'][vid]
    comps = sorted(d['comps'].items(), key=lambda x: (-x[1]['n'], x[0]))
    n = sum(c['n'] for _, c in comps); tot += n
    fields = {}
    for _, c in comps:
        for f, k in c['fields'].items(): fields[f] = fields.get(f, 0) + k
    cl = ', '.join(f"{name} ({c['n']})" for name, c in comps) or '—'
    st = ', '.join(f"`{s}`" for s in d['styles']) or '—'
    L.append(f"| {i} | `{d['name']}` | **{n}** in {len(comps)} | {cl} | {', '.join(f'{f} {k}' for f, k in sorted(fields.items())) or '—'} | {d['otherLayers']} | {len(d['styles'])}: {st} |")
L += ['', f"Total component bindings across the batch: **{tot}**. The 3 primitives (`Brand/600`, `Gray (light mode)/450`, `Spacing/3 (12px)`) have no direct bindings; they reach components only through aliases and the `Brand/600` paint style.", '',
      '> Correction: revision 1 listed colour bindings at twice these numbers (e.g. 840 for `border-primary`; the correct figure is 420). The old scan counted paint-level and node-level bindings separately. Typography figures (716, 184) were already right. The usage scan is now saved as `scripts/naming/live-usage-scan.js` (rule v2).', '',
      '## 5. Collision checks', '',
      '| # | New name | Exists in its collection? | Look-alike in collection (separators/case ignored)? | Same name in another collection? | Preflight |', '|---|---|---|---|---|---|']
for i, vid in enumerate(ORDER, 1):
    d = rd['detail'][vid]
    L.append(f"| {i} | `{d['proposed']}` | {'**YES**' if d['exactNameClash'] else 'no'} | {'**YES** ' + ', '.join(d['lookalikes']) if d['lookalikes'] else 'no'} | {'**YES** ' + ', '.join(d['anyCollectionSameName']) if d['anyCollectionSameName'] else 'no'} | old name matches, target free |")
conf = {c['id']: c for c in au['conflicts']}
L += ['', '**Batch-level checks** (from `reports/token-naming-conflicts.md`): ' + ' · '.join(f"{k} {conf[k]['severity']}" for k in ('C1', 'C2', 'C3', 'C5', 'C6', 'C10', 'C11')) + '.', '',
      '**Things that are not collisions but will be visible:**', '',
      '- **Mixed groups in the picker during the pilot.** New top-level groups `color/`, `spacing/` and `font/` appear next to the existing `Colors/`, `Spacing/`, `Font size/` and `Font weight/` groups until later batches move the rest. Figma treats `color` and `Colors` as different groups, so nothing merges or breaks. It only looks mixed.',
      '- **`Font weight/semibold` is a STRING variable** holding the style name `"Semibold"`. Only its name changes. The generator maps it to `600` from the registry, as the sync map already does.',
      '- **Two batch variables are hidden from publishing** (`focus-ring-primary`, `Spacing/3 (12px)`). That flag is unchanged.', '',
      '## 6. Generated code names for the batch (option A build, compile-checked)', '',
      '| # | Registry token | Tailwind v4 variable | Class(es) | NativeWind v4 | Build handling | Compile check |', '|---|---|---|---|---|---|---|']
ccmap = {r['class']: r for r in cc['results'] if r['scenario'] == 'S1'}
for i, vid in enumerate(ORDER, 1):
    r = rows[vid]
    hit = [ccmap[u] for u in r['utilities'] if u in ccmap]
    if r['build'].startswith('`:root'):
        ccs = 'no utility in option A' + (f" (S1 confirms `{hit[0]['class']}` generates nothing)" if hit and hit[0]['pass'] else '')
    else:
        ccs = ('pass: ' + ', '.join(f"`{h['class']}`" for h in hit)) if hit and all(h['pass'] for h in hit) else '—'
    L.append(f"| {i} | `{r['token']}` | `{r['cssVar']}` | {', '.join('`' + u + '`' for u in r['utilities'])} | `{r['nativewind']}` | {r['build']} | {ccs} |")
s = cc['summary']
L += ['', f"Compile check: Node.js {s['node']} (LTS {s['nodeLts']}), tailwindcss {s['tailwindcss']} (lockfile integrity matched), **{s['passed']}/{s['total']} assertions passed**. It also proves `bg-gray-100`, `rounded-lg` and `font-sans` keep Tailwind's defaults under option A. Evidence: `reports/token-naming/compile-check/`.", '',
      '## 7. Steps', '',
      '| # | Step | Writes | Approval |', '|---|---|---|---|',
      '| 0 | Approve the exact mapping in §2 | — | **Mike** |',
      '| 1 | **Before snapshot:** fresh read of the 11 IDs (name, values, aliases, scopes, code syntax, publishing); live usage scan v2; E1 variant hashes of the affected sets (Button, Button destructive, Input field, Select, Radio group item, Social button, Alert, _Modal header…); `collect-instances` baseline | none | — |',
      '| 2 | **Rename:** `scripts/naming/pilot-rename.js` with `APPLY = true`. Refuses any other file, any old-name mismatch, any existing target name, any count ≠ 11; verifies inside the same call and throws (rolls back) on any mismatch | 11 `variable.name` writes, duplicate only | **Mike** (after step 0) |',
      '| 3 | **Verify** (fresh calls): the 11 new names; IDs, types, values, alias targets, scopes, code syntax and publishing unchanged; §3 aliases still resolve; §4 binding counts and style references identical; E1 hashes unchanged; dry-run `--map` = 0 operations; Light **and** Dark screenshots of Button and Input field identical to before | none | — |',
      '| 4 | **Re-baseline** `collect-instances` (its lines print variable names, so name changes there are expected) | workspace only | — |',
      '| 5 | **Code-gen** for the 11 tokens into `reports/token-naming/pilot-codegen/`: `make-theme.css` (option A: roles in `@theme`, primitives in `:root --make-*`, dark overrides), `make-nativewind.config.js` (NativeWind 4 `theme.extend`, rem 16 note) | workspace only | — |',
      '| 6 | **Compile check** of the generated CSS with `scripts/naming/compile-check.mjs` (Node 26 LTS, tailwindcss 4.3.5) | scratch only | — |',
      '| 7 | **Rollback drill:** `pilot-rename.js` with `ROLLBACK = true` on 1 variable (`Spacing/3 (12px)`, no direct bindings), verify, then re-apply | 2 writes, duplicate only | covered by step 2 approval |',
      '| 8 | Report `reports/token-naming/pilot-report.md` | workspace only | — |', '',
      '## 8. Acceptance criteria', '',
      '- 11/11 renamed to exactly the §2 names; 0 changes to ID, type, values, aliases, scopes, code syntax or publishing flag.',
      f"- Binding counts per variable equal to §4 (total {tot}); style references equal to §4; E1 hashes unchanged; screenshots identical in Light and Dark.",
      '- Dry-run with `--map`: 0 operations.',
      '- Generated CSS/JS deterministic (byte-identical rerun), registry values only, **no Tailwind default key emitted**; every class in §6 compiles to its expected property.',
      '- Rollback drill restores the exact old name by ID.', '',
      '## 9. Not in the pilot', '',
      'Radius (deferred) · Tailwind default overrides (ADR-0009) · Figma-only variables (368) · 171 component colours · Widths/Containers · `3. Spacing` t-shirt variables · text styles / `type-*` composites · code syntax (D-10) · token-repo `com.make.source.figma` updates · publishing · screens.', '',
      '## 10. Decisions needed', '',
      '1. **Approve the exact mapping in §2** (or name rows to drop). Nothing is renamed before this.',
      '2. Radius: accept proposal R1 (name = px value) for a later batch, or keep the current names indefinitely. R1 needs an ADR-0006 amendment and a token-repo change (convention §6).',
      '3. Typography: approve rule T (`type-base-medium`) for generated composites (convention §7).',
      '4. Devs (ADR-0009): option A / B / C / D for Tailwind default keys (`reports/token-naming-conflicts.md` → C4). Option A is safe for the pilot whatever they choose.',
      '5. Devs: confirm app Tailwind / NativeWind / React Native versions (still UNVERIFIED).', '',
      '## Subscription status', '', 'Tokens Studio Free (not used) · unblocked · no paid features · no upgrade.', '']
open(os.path.join(W, 'reports/token-naming-pilot.md'), 'w').write('\n'.join(L) + '\n')
print('pilot written; component bindings', tot)
